package com.agroconnect.service;

import com.agroconnect.api.dto.ApiDtos.*;
import com.agroconnect.domain.*;
import com.agroconnect.repository.*;
import lombok.RequiredArgsConstructor;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.Instant;import java.util.*;

@Service @RequiredArgsConstructor
public class LocalServiceMarketplaceService {
 private final LocalServiceListingRepository listings;private final LocalServiceContactThreadRepository threads;private final LocalServiceMessageRepository messages;
 @Transactional(readOnly=true) public List<LocalServiceListingResponse> search(LocalServiceSearchRequest q){
  boolean coordinates=q.latitude()!=null&&q.longitude()!=null;if((q.latitude()==null)!=(q.longitude()==null))throw new BadRequestException("Send both latitude and longitude or neither");
  if(!coordinates&&(blank(q.village())&&blank(q.taluka())&&blank(q.district())))throw new BadRequestException("Choose a village, district, or allow location access");
  List<LocalServiceListing> found=listings.findByActiveTrueOrderByCreatedAtDesc();List<LocalServiceListingResponse> result=new ArrayList<>();
  for(LocalServiceListing l:found){double distance=coordinates?distance(q.latitude().doubleValue(),q.longitude().doubleValue(),l.getLatitude().doubleValue(),l.getLongitude().doubleValue()):-1;
   if(coordinates&&distance>25)continue;if(!coordinates&&!matches(q,l))continue;if(!blank(q.type())&&!"ALL".equalsIgnoreCase(q.type())&&!q.type().equalsIgnoreCase(l.getListingType()))continue;
   result.add(toListing(l,distance));}
  result.sort(Comparator.comparingDouble(x->x.distanceInKm()<0?999999:x.distanceInKm()));return result;
 }
 @Transactional(readOnly=true) public List<LocalServiceListingResponse> mine(User user){return listings.findByOwner_IdAndActiveTrueOrderByUpdatedAtDesc(user.getId()).stream().map(x->toListing(x,-1)).toList();}
 @Transactional public LocalServiceListingResponse create(User user,LocalServiceListingRequest r){requireFarmer(user);LocalServiceListing l=new LocalServiceListing();l.setOwner(user);apply(l,r);return toListing(listings.save(l),-1);}
 @Transactional public LocalServiceListingResponse update(User user,UUID id,LocalServiceListingRequest r){LocalServiceListing l=findListing(id);if(!l.getOwner().getId().equals(user.getId()))throw new AccessDeniedException("You can edit only your own listing");apply(l,r);return toListing(l,-1);}
 @Transactional public void deactivate(User user,UUID id){LocalServiceListing l=findListing(id);if(!l.getOwner().getId().equals(user.getId()))throw new AccessDeniedException("You can remove only your own listing");l.setActive(false);}
 @Transactional public LocalServiceThreadResponse contact(User user,UUID listingId,LocalServiceContactRequest request){requireFarmer(user);LocalServiceListing listing=findListing(listingId);if(!listing.isActive())throw new BadRequestException("This listing is not available");if(listing.getOwner().getId().equals(user.getId()))throw new BadRequestException("You cannot contact yourself about your own listing");LocalServiceContactThread thread=threads.findByListing_IdAndRequester_Id(listingId,user.getId()).orElseGet(()->{LocalServiceContactThread t=new LocalServiceContactThread();t.setListing(listing);t.setRequester(user);t.setProvider(listing.getOwner());t.setStatus("OPEN");return t;});if(request.requestedDate()!=null&&request.requestedDate().isBefore(java.time.LocalDate.now()))throw new BadRequestException("Requested date must be today or later");thread.setRequestedDate(request.requestedDate());thread.setAreaAcres(request.areaAcres());thread.setUpdatedAt(Instant.now());thread=threads.save(thread);saveMessage(thread,user,request.message());return threadResponse(thread,user.getId());}
 @Transactional public List<LocalServiceThreadResponse> inbox(User user){List<LocalServiceContactThread> rows=threads.findByRequester_IdOrProvider_IdOrderByUpdatedAtDesc(user.getId(),user.getId());Instant now=Instant.now();rows.forEach(t->messages.markIncomingDelivered(t.getId(),user.getId(),now));return rows.stream().map(t->threadResponse(t,user.getId())).toList();}
 @Transactional public List<LocalServiceMessageResponse> messages(User user,UUID threadId){LocalServiceContactThread t=thread(threadId);requireParticipant(user,t);Instant now=Instant.now();messages.markIncomingDelivered(threadId,user.getId(),now);messages.markIncomingRead(threadId,user.getId(),now);List<LocalServiceMessage> rows=messages.findTop100ByThread_IdOrderByCreatedAtDesc(threadId);Collections.reverse(rows);return rows.stream().map(this::messageResponse).toList();}
 @Transactional public LocalServiceMessageResponse reply(User user,UUID threadId,LocalServiceMessageRequest request){LocalServiceContactThread t=thread(threadId);requireParticipant(user,t);LocalServiceMessage m=saveMessage(t,user,request.message());t.setUpdatedAt(Instant.now());threads.save(t);return messageResponse(m);}
 @Transactional public LocalServiceThreadResponse status(User user,UUID threadId,LocalServiceStatusRequest request){LocalServiceContactThread t=thread(threadId);if(!t.getProvider().getId().equals(user.getId()))throw new AccessDeniedException("Only the listing owner can update this request");if(!Set.of("ACCEPTED","REJECTED","COMPLETED","CANCELLED").contains(request.status()))throw new BadRequestException("Unsupported request status");t.setStatus(request.status());return threadResponse(t,user.getId());}
 private void apply(LocalServiceListing l,LocalServiceListingRequest r){if(!r.imageUrl().startsWith("/api/media/"))throw new BadRequestException("Upload a listing photo using the image upload control");if((r.allowCalls()||r.allowWhatsApp())&&(r.contactNumber()==null||r.contactNumber().isBlank()))throw new BadRequestException("Add a contact number to enable calls or WhatsApp");l.setListingType(r.listingType());l.setCategory(r.category().trim());l.setTitle(r.title().trim());l.setDescription(r.description().trim());l.setImageUrl(r.imageUrl());l.setPrice(r.price());l.setRateUnit(r.rateUnit());l.setRateNotes(trimOrNull(r.rateNotes()));l.setContactNumber(trimOrNull(r.contactNumber()));l.setAllowCalls(r.allowCalls());l.setAllowWhatsApp(r.allowWhatsApp());l.setVillage(r.village().trim());l.setTaluka(r.taluka().trim());l.setDistrict(r.district().trim());l.setLatitude(r.latitude());l.setLongitude(r.longitude());l.setAvailability(r.availability().trim());l.setActive(true);}
 private boolean matches(LocalServiceSearchRequest q,LocalServiceListing l){boolean hit=false;if(!blank(q.village()))hit=l.getVillage().equalsIgnoreCase(q.village().trim());if(!blank(q.taluka()))hit=hit||l.getTaluka().equalsIgnoreCase(q.taluka().trim());if(!blank(q.district()))hit=hit||l.getDistrict().equalsIgnoreCase(q.district().trim());return hit;}
 private LocalServiceListingResponse toListing(LocalServiceListing l,double distance){boolean contactAllowed=l.isAllowCalls()||l.isAllowWhatsApp();return new LocalServiceListingResponse(l.getId(),l.getOwner().getId(),l.getOwner().getFullName(),l.getListingType(),l.getCategory(),l.getTitle(),l.getDescription(),l.getImageUrl(),l.getPrice(),l.getRateUnit(),l.getRateNotes(),contactAllowed?publicContactNumber(l.getContactNumber()):null,l.isAllowCalls(),l.isAllowWhatsApp(),l.getVillage(),l.getTaluka(),l.getDistrict(),distance,l.getAvailability(),l.getCreatedAt());}
 private LocalServiceContactThread thread(UUID id){return threads.findById(id).orElseThrow(()->new NotFoundException("Contact request not found"));}private LocalServiceListing findListing(UUID id){return listings.findById(id).orElseThrow(()->new NotFoundException("Listing not found"));}
 private LocalServiceMessage saveMessage(LocalServiceContactThread t,User sender,String text){LocalServiceMessage m=new LocalServiceMessage();m.setThread(t);m.setSender(sender);m.setMessage(text.trim());return messages.save(m);}
 private LocalServiceThreadResponse threadResponse(LocalServiceContactThread t,UUID userId){LocalServiceListing l=t.getListing();return new LocalServiceThreadResponse(t.getId(),l.getId(),l.getTitle(),l.getImageUrl(),l.getVillage(),l.getPrice(),l.getRateUnit(),t.getRequester().getId(),t.getRequester().getFullName(),t.getProvider().getId(),t.getProvider().getFullName(),t.getStatus(),t.getRequestedDate(),t.getAreaAcres(),messages.countUnread(t.getId(),userId),t.getUpdatedAt());}
 private LocalServiceMessageResponse messageResponse(LocalServiceMessage m){return new LocalServiceMessageResponse(m.getId(),m.getSender().getId(),m.getSender().getFullName(),m.getMessage(),m.getDeliveredAt()!=null,m.getReadAt()!=null,m.getCreatedAt());}
 private void requireParticipant(User u,LocalServiceContactThread t){if(!t.getRequester().getId().equals(u.getId())&&!t.getProvider().getId().equals(u.getId()))throw new AccessDeniedException("This contact thread is private");}
 private void requireFarmer(User u){if(u.getRoles()==null||!u.getRoles().contains(Role.FARMER))throw new AccessDeniedException("A farmer account is required");}
 private String trimOrNull(String s){return s==null||s.isBlank()?null:s.trim();}private String publicContactNumber(String s){if(s==null)return null;String digits=s.replaceAll("\\D","");return digits.length()==10?"+91"+digits:s.trim();}private boolean blank(String s){return s==null||s.isBlank();}
 private double distance(double a,double b,double c,double d){double r=6371,lat=Math.toRadians(c-a),lon=Math.toRadians(d-b);double x=Math.sin(lat/2)*Math.sin(lat/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(lon/2)*Math.sin(lon/2);return r*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
}
